def GS(A, b, eps, x_true, x0):
    N = len(b)
    x = x0.copy()
    while True:
        x_prev = x.copy()
        for i in range(N):
            s = 0.0
            for j in range(N):
                if i == j:
                    continue
                s += A[i, j] * x[j]
            x[i] = (b[i] - s) / A[i, i]
        if np.linalg.norm(x - x_prev) < eps:
            break
    residual = np.linalg.norm(A @ x - b)
    error = np.linalg.norm(x - x_true)
    return residual, error
